import java.io.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    private static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] a = new int[n];
        int v = 0;
        for (int i = 0; i < n; i++) {
            a[i] = nextInt();
            v = Math.max(v, a[i]);
        }
        int[] freq = new int[2 * v + 1];
        for (int x : a) freq[x]++;
        int answer = 0;
        for (int t = 1; t <= 2 * v; t++) {
            int count = freq[t]; // single-item bundles
            for (int x = Math.max(1, t - v); x <= Math.min(v, (t - 1) / 2); x++) count += Math.min(freq[x], freq[t - x]);
            if (t % 2 == 0) count += freq[t / 2] / 2;
            answer = Math.max(answer, count);
        }
        System.out.println(answer);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	v := slices.Max(a)
	freq := make([]int, 2*v+1)
	for _, x := range a {
		freq[x]++
	}
	answer := 0
	for t := 1; t <= 2*v; t++ {
		count := freq[t] // single-item bundles
		for x := max(1, t-v); x <= min(v, (t-1)/2); x++ {
			count += min(freq[x], freq[t-x])
		}
		if t%2 == 0 {
			count += freq[t/2] / 2
		}
		answer = max(answer, count)
	}
	os.Stdout.WriteString(strconv.Itoa(answer) + "\n")
}
